    return {m:c for m,c in r.items() if c}

def mul(p,q):
    r={}
    for (i,j),c in p.items():
        for (k,l),d in q.items():
            m=(i+k,j+l)
            r[m]=r.get(m,0)+c*d
    return {m:c for m,c in r.items() if c}

S={(0,0):1,(1,0):1,(0,1):1}
initial=((0,1,{(0,0):1}),(1,2,{(2,0):1,(1,1):2,(0,2):1,(1,0):1}),(1,1,{(1,0):1,(0,1):1}))

def child(f,right):
